def reverseVowels(s):
    vows=set('aeiouAEIOU')
    a=list(s); i=0; j=len(a)-1
    while i<j:
        if a[i] not in vows: i+=1; continue
        if a[j] not in vows: j-=1; continue
        a[i],a[j]=a[j],a[i]; i+=1; j-=1
    return ''.join(a)

