def rob(nums):
    prev2=prev1=0
    for x in nums:
        cur=max(prev1, prev2+x)
        prev2,prev1=prev1,cur
    return prev1

def coinChange(coins, amount):
    INF=amount+1
    dp=[0]+[INF]*amount
    for a in range(1, amount+1):
        for c in coins:
            if c<=a: dp[a]=min(dp[a], dp[a-c]+1)
    return -1 if dp[amount]==INF else dp[amount]

def longestConsecutive(nums):
    s=set(nums); best=0
    for x in s:
        if x-1 not in s:
            y=x
            while y in s: y+=1
            best=max(best, y-x)
    return best

def intersect(nums1,nums2):
    from collections import Counter
    c=Counter(nums1); out=[]
    for x in nums2:
        if c[x]>0: c[x]-=1; out.append(x)
    return out

def thirdMax(nums):
    s=sorted(set(nums))
    return s[-3] if len(s)>=3 else s[-1]

def titleToNumber(columnTitle):
    n=0
    for ch in columnTitle:
        n=n*26+(ord(ch)-64)
    return n

def findMaxAverage(nums,k):
    s=sum(nums[:k]); best=s
    for i in range(k,len(nums)):
        s+=nums[i]-nums[i-k]
        best=max(best,s)
    return best/k

def findContentChildren(g,s_):
    g=sorted(g); s_=sorted(s_); i=j=0
    while i<len(g) and j<len(s_):
        if s_[j]>=g[i]: i+=1
        j+=1
    return i

def twoCitySchedCost(costs):
    costs=sorted(costs,key=lambda c:c[0]-c[1])
    n=len(costs)//2
    return sum(c[0] for c in costs[:n])+sum(c[1] for c in costs[n:])

def mergeAlternately(word1,word2):
    out=[]
    for i in range(max(len(word1),len(word2))):
        if i<len(word1): out.append(word1[i])
        if i<len(word2): out.append(word2[i])
    return ''.join(out)

def majorityElement(nums):
    from collections import Counter
    n=len(nums); t=n//3
    return sorted([k for k,v in Counter(nums).items() if v>t])

def restoreString(s,indices):
    a=['']*len(s)
    for i,ch in enumerate(s): a[indices[i]]=ch
    return ''.join(a)

def numIdenticalPairs(nums):
    from collections import Counter
    return sum(v*(v-1)//2 for v in Counter(nums).values())

def minCostClimbingStairs(cost):
    a=b=0
    for c in cost:
        a,b=b,min(a,b)+c
    return min(a,b)

