def isHappy(n):
    seen=set()
    while n!=1 and n not in seen:
        seen.add(n)
        n=sum(int(d)**2 for d in str(n))
    return n==1

def isPerfectSquare(num):
    r=int(num**0.5)
    return r*r==num

def removeDuplicates(nums):
    if not nums: return 0
    i=0
    for x in nums[1:]:
        if x!=nums[i]: i+=1; nums[i]=x
    return i+1

