def isValid(s):
    stack=[]
    mp={')':'(',']':'[','}':'{'}
    for ch in s:
        if ch in '([{': stack.append(ch)
        else:
            if not stack or stack[-1]!=mp[ch]: return False
            stack.pop()
    return not stack

def dailyTemperatures(temperatures):
    n=len(temperatures); ans=[0]*n; st=[]
    for i,t in enumerate(temperatures):
        while st and temperatures[st[-1]]<t:
            j=st.pop(); ans[j]=i-j
        st.append(i)
    return ans

def isAnagram(s, t):
    from collections import Counter
    return Counter(s)==Counter(t)

def maxDepth(arr):
    if not arr or arr[0] is None: return 0
    # height via level count for complete simulation: depth = ceil(log2(n+1)) for perfect, else BFS sim
    # simplified: count levels by simulating BFS on array representation
    from collections import deque
    q=deque([0]); depth=0
    while q:
        depth+=1
        nxt=[]
        for i in q:
            l=2*i+1; r=2*i+2
            if l < len(arr) and arr[l] is not None: nxt.append(l)
            if r < len(arr) and arr[r] is not None: nxt.append(r)
        q=deque(nxt)
    return depth

def canFinish(numCourses, prerequisites):
    from collections import defaultdict, deque
    g=defaultdict(list); indeg=[0]*numCourses
    for a,b in prerequisites: g[b].append(a); indeg[a]+=1
    q=deque([i for i,d in enumerate(indeg) if d==0])
    seen=0
    while q:
        u=q.popleft(); seen+=1
        for v in g[u]:
            indeg[v]-=1
            if indeg[v]==0: q.append(v)
    return seen==numCourses

def invertTree(arr):
    if not arr or arr[0] is None: return arr
    n=len(arr)
    out=[None]*n; out[0]=arr[0]
    from collections import deque
    q=deque([0]); origin={0:0}; pos=1
    while q and pos<n:
        out_pos=q.popleft(); oi=origin[out_pos]
        l=2*oi+1; r=2*oi+2
        for c in (r,l):
            if c<n and pos<n:
                out[pos]=arr[c]; origin[pos]=c
                if arr[c] is not None: q.append(pos)
                pos+=1
    return out

def maximumProduct(nums):
    nums=sorted(nums)
    return max(nums[-1]*nums[-2]*nums[-3], nums[0]*nums[1]*nums[-1])

def levelOrder(arr):
    if not arr: return []
    out=[]; start=0; end=1; n=len(arr)
    while start<n:
        level=[]
        for i in range(start,min(end,n)):
            if arr[i] is not None: level.append(arr[i])
        if level: out.append(level)
        start=end; end=2*end+1
    return out

def isSymmetric(arr):
    if not arr or arr[0] is None: return True
    start=0; end=1; n=len(arr)
    while start<n:
        lo,hi=start,min(end,n)-1
        while lo<hi:
            if (arr[lo] is not None or arr[hi] is not None) and arr[lo]!=arr[hi]:
                return False
            lo+=1; hi-=1
        start=end; end=2*end+1
    return True

def isValidBST(arr):
    vals=[]
    def inorder(i):
        if i>=len(arr) or arr[i] is None: return
        inorder(2*i+1); vals.append(arr[i]); inorder(2*i+2)
    inorder(0)
    return all(vals[k]<vals[k+1] for k in range(len(vals)-1))

def sortedArrayToBST(nums):
    def build(lo,hi):
        if lo>hi: return None
        m=(lo+hi)//2
        return (nums[m], build(lo,m-1), build(m+1,hi))
    t=build(0,len(nums)-1)
    out=[]; queue=[t]
    while queue and any(x is not None for x in queue):
        nxt=[]
        for node in queue:
            if node is None:
                out.append(None); continue
            out.append(node[0]); nxt.append(node[1]); nxt.append(node[2])
        queue=nxt
    return out

def numJewelsInStones(jewels,stones):
    j=set(jewels)
    return sum(1 for c in stones if c in j)

