    if l1:
        sm += l1.val
        l1 = l1.next
    if l2:
        sm += l2.val
        l2 = l2.next
    carry, v = divmod(sm, 10)
    cur.next = ListNode(v)
    cur = cur.next
print(fmt(to_arr(dummy.next)))

