    data = sys.stdin.read().strip().splitlines()
    k = int(data[0].split("=", 1)[1].strip())
    n = int(data[1].split("=", 1)[1].strip())
    res = []
    def bt(start, remain, combo):
        if len(combo) == k:
            if remain == 0:
                res.append(list(combo))
            return
        if remain < 0:
            return
        for x in range(start, 10):
            if x > remain:
                break
            combo.append(x)
            bt(x + 1, remain - x, combo)
            combo.pop()
    bt(1, n, [])
    print(res)

