def isIsomorphic(s,t):
    if len(s)!=len(t): return False
    ms,mt={},{}
    for cs,ct in zip(s,t):
        if (cs in ms and ms[cs]!=ct) or (ct in mt and mt[ct]!=cs):
            return False
        ms[cs]=ct;mt[ct]=cs
    return True

def getHint(secret,guess):
    bulls=cows=0;sc=[0]*10;gc=[0]*10
    for s,g in zip(secret,guess):
        if s==g: bulls+=1
        else: sc[int(s)]+=1;gc[int(g)]+=1
    for i in range(10): cows+=min(sc[i],gc[i])
    return f'{bulls}A{cows}B'

def isValidSudoku(board):
    rows=[set() for _ in range(9)]
    cols=[set() for _ in range(9)]
    boxs=[set() for _ in range(9)]
    for i in range(9):
        for j in range(9):
            v=board[i][j]
            if v=='.': continue
            bi=(i//3)*3+(j//3)
            if v in rows[i] or v in cols[j] or v in boxs[bi]:
                return False
            rows[i].add(v);cols[j].add(v);boxs[bi].add(v)
    return True

