def trap(height):
    l,r=0,len(height)-1;lm=rm=water=0
    while l<r:
        if height[l]<height[r]:
            if height[l]>=lm: lm=height[l]
            else: water+=lm-height[l]
            l+=1
        else:
            if height[r]>=rm: rm=height[r]
            else: water+=rm-height[r]
            r-=1
    return water

def maxArea(height):
    l,r=0,len(height)-1;best=0
    while l<r:
        w=r-l
        if height[l]<height[r]:
            best=max(best,height[l]*w);l+=1
        else:
            best=max(best,height[r]*w);r-=1
    return best

def characterReplacement(s,k):
