def findMedianSortedArrays(n1,n2):
    if len(n1)>len(n2): n1,n2=n2,n1
    m,n=len(n1),len(n2);lo,hi=0,m
    while lo<=hi:
        i=(lo+hi)//2;j=(m+n+1)//2-i
        l1=n1[i-1] if i>0 else float('-inf')
        r1=n1[i] if i<m else float('inf')
        l2=n2[j-1] if j>0 else float('-inf')
        r2=n2[j] if j<n else float('inf')
        if l1<=r2 and l2<=r1:
            return (max(l1,l2)+min(r1,r2))/2 if (m+n)%2==0 else max(l1,l2)
        elif l1>r2: hi=i-1
        else: lo=i+1

