def detectCycle(head):
    s=f=head
    while f and f.next:
        s=s.next;f=f.next.next
        if s==f:
            s=head
            while s!=f: s=s.next;f=f.next
            return s
    return None

def reverseKGroup(head,k):
    c=0;cur=head
    while cur and c<k: cur=cur.next;c+=1
    if c==k:
        prev=reverseKGroup(cur,k)
        for _ in range(k):
            nxt=head.next;head.next=prev
            prev=head;head=nxt
        head=prev
    return head

