def maxDepth(root):
    if not root: return 0
    return 1+max(maxDepth(root.left),maxDepth(root.right))

def isSameTree(p,q):
    if not p and not q: return True
    if not p or not q or p.val!=q.val: return False
    return isSameTree(p.left,q.left) and isSameTree(p.right,q.right)

def levelOrder(root):
    if not root: return []
    from collections import deque
    res=[];q=deque([root])
    while q:
        lvl=[]
        for _ in range(len(q)):
            n=q.popleft();lvl.append(n.val)
            if n.left: q.append(n.left)
            if n.right: q.append(n.right)
        res.append(lvl)
    return res

def isSymmetric(root):
    def mirror(l,r):
        if not l and not r: return True
        if not l or not r or l.val!=r.val: return False
        return mirror(l.left,r.right) and mirror(l.right,r.left)
    return mirror(root.left,root.right)

def isValidBST(root):
    def f(n,lo,hi):
        if not n: return True
        if n.val<=lo or n.val>=hi: return False
        return f(n.left,lo,n.val) and f(n.right,n.val,hi)
    return f(root,float('-inf'),float('inf'))

def inorderTraversal(root):
    res=[];st=[];cur=root
    while cur or st:
        while cur: st.append(cur);cur=cur.left
        cur=st.pop();res.append(cur.val);cur=cur.right
    return res

def hasPathSum(root,targetSum):
    if not root: return False
    if not root.left and not root.right: return targetSum==root.val
    return hasPathSum(root.left,targetSum-root.val) or hasPathSum(root.right,targetSum-root.val)

def zigzagLevelOrder(root):
    if not root: return []
    from collections import deque
    res=[];q=deque([root]);ltr=True
    while q:
        lvl=deque()
        for _ in range(len(q)):
            n=q.popleft()
            if ltr: lvl.append(n.val)
            else: lvl.appendleft(n.val)
            if n.left: q.append(n.left)
            if n.right: q.append(n.right)
        res.append(list(lvl));ltr=not ltr
    return res

