def deserialize(data):
    if data=='[]': return None
    vals=data[1:-1].split(',');i=1
    root=TreeNode(int(vals[0]));q=deque([root])
    while q and i<len(vals):
        n=q.popleft()
        if vals[i]!='null': n.left=TreeNode(int(vals[i]));q.append(n.left)
        i+=1
        if i<len(vals) and vals[i]!='null': n.right=TreeNode(int(vals[i]));q.append(n.right)
        i+=1
    return root

def diameterOfBinaryTree(root):
    best=0
    def dfs(n):
        nonlocal best
        if not n: return 0
        l=dfs(n.left);r=dfs(n.right)
        best=max(best,l+r)
        return 1+max(l,r)
    dfs(root);return best

def preorderTraversal(root):
