    res=[];st=[root]
    while st:
        n=st.pop();res.append(n.val)
        if n.right: st.append(n.right)
        if n.left: st.append(n.left)
    return res

class Trie:
    class Node:
        def __init__(self):
            self.children={};self.is_end=False
    def __init__(self): self.root=self.Node()
    def insert(self,word):
        n=self.root
        for c in word:
            if c not in n.children: n.children[c]=self.Node()
            n=n.children[c]
        n.is_end=True
    def search(self,word):
        n=self.root
        for c in word:
            if c not in n.children: return False
            n=n.children[c]
        return n.is_end
    def startsWith(self,prefix):
        n=self.root
        for c in prefix:
            if c not in n.children: return False
            n=n.children[c]
        return True

class AutocompleteSystem:
    def __init__(self,sentences,times):
        self.trie={};self.input_str=''
        for s,t in zip(sentences,times): self.add(s,t)
    def add(self,s,t):
        n=self.trie
        for c in s:
            if c not in n: n[c]={}
            n=n[c]
        n['#']=n.get('#',0)+t
    def input(self,c):
        if c=='#':
            self.add(self.input_str,1);self.input_str='';return[]
        self.input_str+=c;n=self.trie
        for ch in self.input_str:
            if ch not in n: return[]
            n=n[ch]
        res=[]
        def dfs(s,n):
            if '#' in n: res.append((n['#'],s))
            for ch in n:
                if ch!='#': dfs(s+ch,n[ch])
        dfs(self.input_str,n)
        return [s for _,s in sorted(res,key=lambda x:(-x[0],x[1]))[:3]]

