        self.time+=1
        if userId not in self.tweets: self.tweets[userId]=[]
        self.tweets[userId].append((self.time,tweetId))
    def getNewsFeed(self,userId):
        users=self.follows.get(userId,set())|{userId};feeds=[]
        for u in users:
            for t in self.tweets.get(u,[])[-10:]: feeds.append(t)
        return [tid for _,tid in sorted(feeds,reverse=True)[:10]]
    def follow(self,followerId,followeeId):
        if followerId not in self.follows: self.follows[followerId]=set()
        self.follows[followerId].add(followeeId)
    def unfollow(self,followerId,followeeId):
        self.follows.get(followerId,set()).discard(followeeId)

import heapq
def maxProfit(k,prices):
    heap=[];n=len(prices)
    for i in range(n-1):
        if prices[i]<prices[i+1]:
            heapq.heappush(heap,(prices[i]-prices[i+1],prices[i],prices[i+1]))
        if len(heap)>k: heapq.heappop(heap)
    return -sum(t[0] for t in heap)

def canVisitAllRooms(n,edges):
    adj=[[] for _ in range(n)]
    for u,v in edges: adj[u].append(v);adj[v].append(u)
    visited=[False]*n
    def dfs(u):
        visited[u]=True
        for v in adj[u]:
            if not visited[v]: dfs(v)
    dfs(0)
    return all(visited)

