from ast import literal_eval
from functools import lru_cache
matrix = literal_eval(input().replace('null', 'None'))
m, n = len(matrix), len(matrix[0])
@lru_cache(None)
def dfs(r, c):
    best = 1
    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
        nr, nc = r + dr, c + dc
        if 0 <= nr < m and 0 <= nc < n and matrix[nr][nc] > matrix[r][c]:
            best = max(best, 1 + dfs(nr, nc))
    return best
print(str(max(dfs(r, c) for r in range(m) for c in range(n))))

from ast import literal_eval
class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next
def build(arr):
    dummy = cur = ListNode(0)
    for v in arr:
        cur.next = ListNode(v)
        cur = cur.next
    return dummy.next
def to_arr(head):
    out = []
    while head:
        out.append(head.val)
        head = head.next
    return out
def fmt(x):
    if isinstance(x, bool):
        return 'true' if x else 'false'
    if x is None:
        return 'null'
    if isinstance(x, str):
        return '"' + x + '"'
    if isinstance(x, list):
        return '[' + ','.join(fmt(i) for i in x) + ']'
    return str(x)
head = build(literal_eval(input().replace('null', 'None')))
if not head or not head.next:
    print(fmt(to_arr(head)))
